package com.interview.fraud.casework;
import com.interview.fraud.ai.AiInvestigationService; import com.interview.fraud.platform.AuditService; import com.interview.fraud.transaction.TransactionRequest; import jakarta.validation.Valid; import java.security.Principal; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class CaseController {private final CaseWorkflowService workflow;private final AiInvestigationService ai;private final AuditService audit;public CaseController(CaseWorkflowService w,AiInvestigationService a,AuditService l){workflow=w;ai=a;audit=l;}
 @PostMapping("/transactions") @ResponseStatus(HttpStatus.CREATED) public CaseView ingest(@Valid @RequestBody TransactionRequest r,@RequestHeader(value="Idempotency-Key",required=false)String key,Principal p){return workflow.ingest(r,key==null?r.transactionId():key,p.getName());}
 @GetMapping("/cases") public List<CaseView> cases(){return workflow.list();}@GetMapping("/cases/{id}/signals") public List<Map<String,Object>> signals(@PathVariable UUID id){return workflow.signals(id);}@PostMapping("/cases/{id}/investigate") public Object investigate(@PathVariable UUID id,Principal p){return ai.investigate(id,p.getName());}
 @PostMapping("/cases/{id}/approve") public CaseView approve(@PathVariable UUID id,@RequestBody Approval r,Principal p){return workflow.approve(id,r.action(),r.rationale(),p.getName(),r.version());}@GetMapping("/cases/{id}/audit") public List<Map<String,Object>> audit(@PathVariable UUID id){return audit.forEntity("CASE",id.toString());}public record Approval(String action,String rationale,long version){} }
